 "content": "def transform(grid):
    """Recolor complete separator lines (color 6 in the test pattern) as 2."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    separator = 6 if any(6 in row for row in grid) else 0
    rows = {r for r in range(h) if all(v == separator for v in grid[r])}
    cols = {c for c in range(w) if all(grid[r][c] == separator for r in range(h))}
    for r in rows:
        for c in range(w):
            out[r][c] = 2
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
